{
  "references": [
    {
      "id": "R1",
      "summary_ko": "샐러드로 변하지 않고 그릇 안으로 그냥 던져지기만 함."
    },
    {
      "id": "R2",
      "summary_ko": "상추가 그릇에 떨어지는 방식이 비현실적이며 당근이 갑자기 나타남."
    }
  ],
  "candidates": [
    {
      "id": "C1",
      "summary_ko": "금속 그릇 안의 야채들이 요리사에 의해 놓이지 않고 저절로 나타남."
    },
    {
      "id": "C2",
      "summary_ko": "양배추가 위로 던져지면서 두 개로 분리되고 형태가 변형됨."
    },
    {
      "id": "C3",
      "summary_ko": "던져진 양배추가 공중에서 모양, 질감, 크기를 계속 바꾸며 상추 잎으로 변형됨."
    },
    {
      "id": "C4",
      "summary_ko": "조리대 위 금속 그릇 안에 채소와 썰린 농산물이 놓이지 않고 저절로 생겨남."
    }
  ],
  "pairs": [
    {
      "reference_id": "R1",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "R1은 샐러드로 변하지 않고 던져지기만 한다는 내용이고, C1은 그릇 안에 야채가 저절로 나타난다는 내용으로 서로 다릅니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "R1은 샐러드가 되지 않는다는 점을 지적하지만 C2는 양배추의 분리 및 형태 변형에 대한 설명으로 다릅니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C3",
      "verdict": "different",
      "reason_ko": "R1은 단순히 그릇으로 던져지기만 한다는 내용이고, C3는 공중에서 양배추가 상추로 형태 변형되는 현상에 관한 것입니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C4",
      "verdict": "different",
      "reason_ko": "R1은 재료가 샐러드로 변하지 않는 것에 대한 서술인 반면, C4는 금속 그릇 안에 야채가 갑자기 생겨나는 결함에 관한 것입니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C1",
      "verdict": "uncertain",
      "reason_ko": "R2는 상추가 떨어지는 방식과 당근의 갑작스러운 출현을 언급하고, C1은 그릇 안 채소들의 자발적 출현을 언급하여 부분적으로 겹치나 동일 현상인지 불확실합니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "R2는 상추의 낙하 및 당근의 출현을 지적하고, C2는 양배추가 공중으로 던져질 때 분리 및 변형되는 현상을 다룹니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C3",
      "verdict": "different",
      "reason_ko": "R2는 그릇으로 떨어지는 상추와 당근의 출현에 대한 것이고, C3는 양배추가 공중에서 상추로 변형되는 현상에 대한 것입니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C4",
      "verdict": "uncertain",
      "reason_ko": "R2의 당근의 갑작스러운 출현과 C4의 그릇 내부 채소들의 자발적 출현이 유사하지만 대상과 결함의 세부 묘사가 달라 동일한지 명확하지 않습니다."
    }
  ]
}
